h f\!\left( y_0 + \sum_{t \in T} \theta(t) \frac{h^{r(t)}}{\sigma(t)} F(t)(y_0) \right).
\]

\begin{center}
\textbf{Table 310(II) \quad Elementary differentials for orders 1 to 5}
\end{center}
\[
\begin{array}{cccc}
r(t) & t & \alpha(t) & F(t)(y) & F(t)(y)^i \\
1 & \bullet & 1 & f & f^i
\end{array}
\]
\end{definition}
